package com.wtm.importer;
import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;
public final class FloorDenialKpiProfile implements KpiCsvImportProfile{
 public boolean supports(CsvTable t){return t.headers().contains("denialtype")&&t.headers().contains("date")&&t.headers().contains("order")&&t.headers().contains("line");}
 public KpiImportResult parse(CsvTable t)throws Exception{TreeMap<LocalDate,Set<String>>daily=new TreeMap<>();List<String>w=new ArrayList<>();for(Map<String,String>r:t.rows()){LocalDate d=date(r.get("date"));if(d==null){w.add("Skipped a denial row with an invalid Date.");continue;}String key=clean(r.get("order"))+"|"+clean(r.get("line"))+"|"+clean(r.get("item"))+"|"+clean(r.get("denialtype"));daily.computeIfAbsent(d,k->new LinkedHashSet<>()).add(key);}if(daily.isEmpty())throw new IllegalArgumentException("No dated Floor Denial records could be imported.");LocalDate first=daily.firstKey(),last=daily.lastKey();List<KpiImportedMetric>history=new ArrayList<>();for(Map.Entry<LocalDate,Set<String>>e:daily.entrySet())history.add(new KpiImportedMetric("floor_denials","Floor Denials",e.getValue().size(),"",e.getKey(),"CSV_FLOOR_DENIALS"));double count=daily.get(last).size();return new KpiImportResult("Floor Denials",t.rows().size(),first,last,List.of(new KpiImportedMetric("floor_denials","Floor Denials",count,"",last,"CSV_FLOOR_DENIALS")),history,w);}
 private static String clean(String v){return v==null?"":v.trim();}
 private static LocalDate date(String raw){if(raw==null||raw.isBlank())return null;String v=raw.trim();try{if(v.length()>=19)return LocalDateTime.parse(v.substring(0,19),DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm:ss")).toLocalDate();}catch(Exception ignored){}try{if(v.length()>=10)return LocalDate.parse(v.substring(0,10));}catch(Exception ignored){}for(DateTimeFormatter f:List.of(DateTimeFormatter.ofPattern("M/d/uuuu H:mm:ss"),DateTimeFormatter.ofPattern("M/d/uuuu"))){try{return v.contains(":")?LocalDateTime.parse(v,f).toLocalDate():LocalDate.parse(v,f);}catch(Exception ignored){}}return null;}
}
